const runId = $('Start match_run').item.json.match_run_id;
const items = $input.all();

const esc = (v) => `'${String(v).replace(/'/g, "''")}'`;

const rows = [];
for (const item of items) {
  const userId = item.json.user_id;
  const products = Array.isArray(item.json.products) ? item.json.products : [];

  // Cap at top 5 lowest-interest-rate loans per user
  const topProducts = products.slice(0, 5);

  topProducts.forEach((p) => {
    const reasonCodes = "ARRAY['income_ok','credit_ok','employment_ok','age_ok']::text[]";
    const reasonText = `'Eligible based on income, credit score, age, and employment criteria'`;

    rows.push(`(${esc(userId)}, ${esc(p.product_id)}, ${esc(runId)}, ${reasonCodes}, ${reasonText})`);
  });
}

if (rows.length === 0) {
  return [{ json: { upsert_sql: 'SELECT 1;' } }];
}

// Chunk into batches of 2,000 rows for lightning-fast database insertion
const chunkSize = 2000;
const chunks = [];
for (let i = 0; i < rows.length; i += chunkSize) {
  const chunkRows = rows.slice(i, i + chunkSize);
  const sql = `
    INSERT INTO matches (user_id, product_id, match_run_id, reason_codes, reason_text)
    VALUES ${chunkRows.join(',\n')}
    ON CONFLICT (user_id, product_id, match_run_id) DO NOTHING;
  `;
  chunks.push({ json: { upsert_sql: sql } });
}

return chunks;
